import {utilityTrendSnapshot} from './utility-trends.js?v=performing-arts-center-1';
export function cityGrowthTargets(c){return [5000,20000,25000,50000,100000,150000].map(population=>({population,done:c.stats.population>=population}));}
export function cityGrowthGuide(c){const n=v=>Math.round(v||0).toLocaleString('en-US'),u=utilityTrendSnapshot(c),backlog=c.stats.uncollectedWaste||0;return `<details><summary>From town to city · ${n(c.stats.population)} / 150,000 residents</summary><p>Use these practice milestones to plan the next expansion. They describe your population now and can become incomplete if residents leave.</p><ol>${cityGrowthTargets(c).map(t=>`<li>${t.done?'✓ ':''}<strong>${n(t.population)} residents</strong></li>`).join('')}</ol>${cityGrowthDiagnosis(c)}<p><strong>Grow in stages.</strong> Start with connected homes, shops and industry. Add water before raising density, and expand workplaces alongside housing. High-density zoning alone cannot overcome weak demand or low land value.</p><p><strong>Make room for taller buildings.</strong> Parks, healthy roads, low pollution and effective public safety help land value. Separate polluting industry from homes and offices. Check Zone development to see what blocks each neighborhood.</p><p><strong>Keep infrastructure ahead of growth.</strong> Citywide spare electricity: ${n(u.powerAvailable-u.powerDemand)} units; spare water: ${n(u.waterAvailable-u.waterDemand)}. These totals do not guarantee service across disconnected networks. Add supply before building out another district.</p><p><strong>Plan beyond landfill.</strong> Uncollected garbage: ${n(backlog)} units. ${backlog?'Clear the backlog before expanding; garbage can lower land value and empty buildings.':'Keep checking disposal as the population grows.'} Landfills fill over time. Recycling, incineration, waste-to-energy or neighbor exports can support continued growth.</p><p><strong>Protect the budget and review rewards.</strong> Treasury: §${n(c.funds)}; current monthly balance: §${n(c.stats.balance)}. Build in affordable stages and review Rewards as your population rises. If homes stop growing, check residential capacity as well as local services and demand.</p></details>`;}

export function cityGrowthIssues(c){
 const s=c.stats,u=utilityTrendSnapshot(c),n=v=>Math.round(v||0).toLocaleString('en-US'),issues=[],add=(id,text,action,button)=>issues.push({id,text,action,button});
 if(u.powerUnserved>1e-7||u.waterUnserved>1e-7)add('utilities','Some demand is unserved. Fix the affected power or water network before expanding.','utilities','Inspect utility networks');
 if(s.uncollectedWaste>1e-7)add('waste','Uncollected garbage is accumulating. Expand working disposal or arrange exports.','utilities','Review waste disposal');
 if(c.funds<0||s.balance<0)add('budget','The treasury or monthly balance is negative. Review recurring costs before adding another district.','budget','Review the budget');
 if(s.residentialCap?.remaining<=0)add('housing-cap','The residential capacity limit has been reached. Parks, recreation and eligible rewards can make room for more residents.','park','Choose parks');
 const rows=s.demandBreakdown?.residential||[],amount=label=>rows.find(r=>r.label===label)?.amount||0;
 if(s.demand?.residential<=0&&amount('Available jobs')+amount('Existing residents')<0)add('workplaces',`The city has ${n(s.population)} residents and ${n(s.jobs)} jobs. Existing residents outweigh available jobs in residential demand. Develop additional workplaces and check that residents can reach them.`,'industrial','Zone more industry');
 if(s.population>0&&s.economicCaps?.commercial?.remaining<48)add('commercial-cap',`Commercial employment is near its citywide limit of ${n(s.economicCaps.commercial.limit)} jobs, with room for ${n(s.economicCaps.commercial.remaining)} more. More commercial zoning alone may not help; review regional connections and airport capacity.`,'transport','Review regional transport');
 if(s.population>0&&s.economicCaps?.industrial?.remaining<24)add('industrial-cap',`Industrial employment is near its citywide limit of ${n(s.economicCaps.industrial.limit)} jobs, with room for ${n(s.economicCaps.industrial.remaining)} more. Review regional connections and seaport capacity before adding more industry.`,'transport','Review regional transport');
 if(amount('Congested roads and highways')<0)add('traffic','Road and highway congestion is reducing residential demand. Check commuting routes and transit coverage.','transport','Inspect commuting');
 return issues;
}
export function cityGrowthDiagnosis(c){const issues=cityGrowthIssues(c);return `<h3>Before the next district</h3>${issues.length?`<ul>${issues.map(i=>`<li><p>${i.text}</p><button data-town-action="${i.action}">${i.button}</button></li>`).join('')}</ul>`:'<p>No citywide warning is flagged by these checks. Inspect individual zones for local development limits before expanding.</p>'}<p>These checks use current demand, service and capacity reports. They do not predict how many residents will move in or guarantee a reward.</p>`;}
